mapper.select:
select con.con_id as conId, con.con_name AS contractName, con.con_code AS contractCode, ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) AS contractAmt, pany.c_name AS companyName, (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7' ) AS paymentAmtTotal,
CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE((( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) )), 1) * 100, 2) END AS fkjindu,
app.sa_approved_amt as settlement FROM Con_Contract con LEFT JOIN con_pay pay ON pay.con_id = con.con_id left join Inv_Settlement_Apply app on con.con_id = app.con_id left join sys_company pany on con.Con_Party_B_Id = pany.c_id left join Con_Pay_Apply appl on appl.con_id = con.con_id LEFT join Con_Pay_Apply_Flow flow on flow.con_id =con.con_id
flow.State = '7'
and con.con_name like '%${statisticsVo.contractName}%'
and likeCname(#{statisticsVo.companyName},pany.c_id)=true
and pany.c_name like '%${statisticsVo.companyName}%'
and con.con_code like '%${statisticsVo.contractNumber}%'
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7' ) >= #{statisticsVo.paymentAmountStr}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7' ) <= #{statisticsVo.paymentAmountEnd}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7' ) BETWEEN #{statisticsVo.paymentAmountStr} AND #{statisticsVo.paymentAmountEnd}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) >= #{statisticsVo.contractAmtStr}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) <= #{statisticsVo.contractAmtEnd}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) BETWEEN #{statisticsVo.contractAmtStr} AND #{statisticsVo.contractAmtEnd}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END >= #{statisticsVo.paymentSpeedStr}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END <= #{statisticsVo.paymentSpeedEnd}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END BETWEEN #{statisticsVo.paymentSpeedStr} AND #{statisticsVo.paymentSpeedEnd}
AND app.sa_approved_amt >= #{statisticsVo.settlementStr}
AND app.sa_approved_amt <= #{statisticsVo.settlementEnd}
AND app.sa_approved_amt BETWEEN #{statisticsVo.settlementStr} AND #{statisticsVo.settlementEnd}
group by con.con_id, con.con_name, con.con_code, con.Con_Money_Total, pany.c_name, app.sa_approved_amt,app.sa_state_time order by con.con_name, app.sa_state_time desc

SELECT ject.p_id AS pId, ject.p_name AS pName, con.con_id, con.con_name AS contractName, con.con_code AS contractCode, con.con_Create_User_Id as conCreateUserId, con.con_Create_User_Name AS conCreateUserName, ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) AS contractAmt, pany.c_name AS companyName, (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7' ) AS paymentAmtTotal, CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ), 1) * 100, 2) END AS fkjindu from Pre_Project ject LEFT JOIN Con_Contract con ON ject.p_id = con.con_project_id LEFT JOIN ( SELECT con_id, MAX(sa_state_time) AS sa_state_time FROM Inv_Settlement_Apply GROUP BY con_id ) app ON con.con_id = app.con_id LEFT JOIN con_pay pay ON pay.con_id = con.con_id LEFT JOIN sys_company pany ON con.Con_Party_B_Id = pany.c_id left join Con_Pay_Apply appl on appl.con_id = con.con_id
AND EXISTS ( SELECT 1 FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7' ) and ject.p_id is not null
and con.con_name like '%${statisticsVo.contractName}%'
and likeCname(#{statisticsVo.companyName},pany.c_id)=true
and pany.c_name like '%${statisticsVo.companyName}%'
and con.con_code like '%${statisticsVo.contractNumber}%'
and likePname(#{statisticsVo.projectName},ject.P_Id)=true
and ject.p_name like '%${statisticsVo.projectName}%'
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END >= #{statisticsVo.paymentSpeedStr}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END <= #{statisticsVo.paymentSpeedEnd}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END BETWEEN #{statisticsVo.paymentSpeedStr} AND #{statisticsVo.paymentSpeedEnd}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) >= #{statisticsVo.contractAmtStr}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) <= #{statisticsVo.contractAmtEnd}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) BETWEEN #{statisticsVo.contractAmtStr} AND #{statisticsVo.contractAmtEnd}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7') >= #{statisticsVo.paymentAmountStr}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7') <= #{statisticsVo.paymentAmountEnd}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7') BETWEEN #{statisticsVo.paymentAmountStr} AND #{statisticsVo.paymentAmountEnd}
group by ject.p_id, ject.p_name, con.con_id, con.con_name, con.con_code, con.Con_Money_Total, con.con_Create_User_Id, con.con_Create_User_Name, pany.c_name,app.sa_state_time order by ject.p_name, app.sa_state_time desc

SELECT ject.p_id AS pId, ject.p_name AS pName, mn.con_id, mn.con_name AS contractName, mn.con_code AS contractCode, total.contractAmt AS contractAmt, pany.c_name AS companyName, payTotal.paymentAmtTotal AS paymentAmtTotal, CASE WHEN total.contractAmt = 0 THEN 0 ELSE ROUND(COALESCE(payTotal.paymentAmtTotal, 0) / NULLIF(total.contractAmt, 0) * 100, 2) END AS fkjindu from Pre_Project ject LEFT JOIN Con_Contract mn ON ject.p_id = mn.con_project_id LEFT JOIN ( SELECT c.con_id, ( c.Con_Money_Total + COALESCE(sup.sup_change_amt, 0) ) AS contractAmt FROM Con_Contract c LEFT JOIN ( SELECT cc.Con_Master_Con_Id AS con_id, SUM(CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -cc.Con_Sup_Change_Money ELSE 0 END) AS sup_change_amt FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 GROUP BY cc.Con_Master_Con_Id ) sup ON sup.con_id = c.con_id ) total ON mn.con_id = total.con_id LEFT JOIN ( SELECT ff.con_id, SUM(ff.cpaf_application) AS paymentAmtTotal FROM Con_Pay_Apply_Flow ff WHERE ff.State = '7' GROUP BY ff.con_id ) payTotal ON payTotal.con_id = mn.con_id LEFT JOIN ( SELECT con_id, MAX(sa_approved_amt) sa_approved_amt, MAX(sa_state_time) sa_state_time FROM Inv_Settlement_Apply GROUP BY con_id ) app ON mn.con_id = app.con_id LEFT JOIN sys_company pany ON mn.Con_Party_B_Id = pany.c_id ${authSql} and mn.con_id is not null AND mn.con_Type NOT IN ('07','0701','0702','0703') AND mn.Con_Approval_State = 7
and mn.con_name like '%${statisticsVo.contractName}%'
and likeCname(#{statisticsVo.companyName},pany.c_id)=true
and pany.c_name like '%${statisticsVo.companyName}%'
and mn.con_code like '%${statisticsVo.contractNumber}%'
and likePname(#{statisticsVo.projectName},ject.p_id)=true
and ject.p_name like '%${statisticsVo.projectName}%'
AND CASE WHEN total.contractAmt = 0 THEN 0 ELSE ROUND(COALESCE(payTotal.paymentAmtTotal, 0) / NULLIF(total.contractAmt, 0) * 100, 2) END >= #{statisticsVo.paymentSpeedStr}
AND CASE WHEN total.contractAmt = 0 THEN 0 ELSE ROUND(COALESCE(payTotal.paymentAmtTotal, 0) / NULLIF(total.contractAmt, 0) * 100, 2) END <= #{statisticsVo.paymentSpeedEnd}
AND CASE WHEN total.contractAmt = 0 THEN 0 ELSE ROUND(COALESCE(payTotal.paymentAmtTotal, 0) / NULLIF(total.contractAmt, 0) * 100, 2) END BETWEEN #{statisticsVo.paymentSpeedStr} AND #{statisticsVo.paymentSpeedEnd}
and total.contractAmt >= #{statisticsVo.contractAmtStr}
and total.contractAmt <= #{statisticsVo.contractAmtEnd}
and total.contractAmt BETWEEN #{statisticsVo.contractAmtStr} AND #{statisticsVo.contractAmtEnd}
AND COALESCE(payTotal.paymentAmtTotal,0) >= #{statisticsVo.paymentAmountStr}
AND COALESCE(payTotal.paymentAmtTotal,0) <= #{statisticsVo.paymentAmountEnd}
AND COALESCE(payTotal.paymentAmtTotal,0) BETWEEN #{statisticsVo.paymentAmountStr} AND #{statisticsVo.paymentAmountEnd}
AND COALESCE(app.sa_approved_amt,0) >= #{statisticsVo.settlementStr}
AND COALESCE(app.sa_approved_amt,0) <= #{statisticsVo.settlementEnd}
group by ject.p_id, ject.p_name, mn.con_id, mn.con_name, mn.con_code, total.contractAmt, pany.c_name, payTotal.paymentAmtTotal, app.sa_state_time
ORDER BY mn.con_name ASC

SELECT ject.p_id AS pId, ject.p_name AS pName, mn.con_id, mn.con_name AS contractName, mn.con_code AS contractCode, ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) AS contractAmt, pany.c_name AS companyName, (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id and ff.State = '7' ) AS paymentAmtTotal, -- 修复：防除0，分母用 NULLIF(xxx,0)，如果为0则返回NULL，不会报错 CASE WHEN ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) = 0 THEN 0 ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id and ff.State = '7'), 0) / NULLIF(( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ), 0) * 100, 2) END AS fkjindu from Pre_Project ject LEFT JOIN Con_Contract mn ON ject.p_id = mn.con_project_id LEFT JOIN ( SELECT con_id, MAX(sa_approved_amt) sa_approved_amt, MAX(sa_state_time) sa_state_time FROM Inv_Settlement_Apply GROUP BY con_id ) app ON mn.con_id = app.con_id LEFT JOIN con_pay pay ON pay.con_id = mn.con_id LEFT JOIN sys_company pany ON mn.Con_Party_B_Id = pany.c_id left join Con_Pay_Apply appl on appl.con_id = mn.con_id LEFT join Con_Pay_Apply_Flow flow on flow.con_id =mn.con_id ${authSql} and mn.con_id is not null AND mn.con_Type NOT IN ('07','0701','0702','0703') AND mn.Con_Approval_State = 7
and mn.con_name like '%${statisticsVo.contractName}%'
and likeCname(#{statisticsVo.companyName},pany.c_id)=true
and pany.c_name like '%${statisticsVo.companyName}%'
and mn.con_code like '%${statisticsVo.contractNumber}%'
and likePname(#{statisticsVo.projectName},ject.p_id)=true
and ject.p_name like '%${statisticsVo.projectName}%'
AND CASE WHEN ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) = 0 THEN 0 ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id and ff.State = '7'), 0) / NULLIF(( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ), 0) * 100, 2) END >= #{statisticsVo.paymentSpeedStr}
AND CASE WHEN ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) = 0 THEN 0 ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id and ff.State = '7'), 0) / NULLIF(( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ), 0) * 100, 2) END <= #{statisticsVo.paymentSpeedEnd}
AND CASE WHEN ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) = 0 THEN 0 ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id and ff.State = '7'), 0) / NULLIF(( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ), 0) * 100, 2) END BETWEEN #{statisticsVo.paymentSpeedStr} AND #{statisticsVo.paymentSpeedEnd}
and ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) >= #{statisticsVo.contractAmtStr}
and ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) <= #{statisticsVo.contractAmtEnd}
and ( mn.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = mn.con_id), 0 ) ) BETWEEN #{statisticsVo.contractAmtStr} AND #{statisticsVo.contractAmtEnd}
AND COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id AND ff.State = '7'),0) >= #{statisticsVo.paymentAmountStr}
AND COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = mn.con_id AND ff.State = '7'),0) <= #{statisticsVo.paymentAmountEnd}
