AND COALESCE(app.sa_approved_amt,0) <= #{statisticsVo.settlementEnd}
group by ject.p_id, ject.p_name, mn.con_id, mn.con_name, mn.con_code, mn.Con_Money_Total, pany.c_name, app.sa_state_time order by ject.p_name, app.sa_state_time desc

select con.con_id as conId, con.con_name as contractName, con.con_code AS contractCode, ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) AS contractAmt, pany.c_name AS companyName, (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7' ) AS paymentAmtTotal, CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'),0) / COALESCE((( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) ),1) * 100,2) END AS fkjindu, app.sa_approved_amt as settlement from Con_Contract con left join Con_Pay_Apply appl on appl.con_id = con.con_id LEFT join Con_Pay_Apply_Flow flow on flow.con_id = con.con_id LEFT JOIN con_pay pay ON pay.con_id = con.con_id LEFT JOIN sys_company pany ON con.Con_Party_B_Id = pany.c_id left join Inv_Settlement_Apply app on con.con_id = app.con_id where flow.State = '7' and app.sa_state = '7'
and con.con_name like concat('%',#{statisticsVo.contractName},'%')
and pany.c_name like concat('%',#{statisticsVo.companyName},'%')
and con.con_code like concat('%',#{statisticsVo.contractNumber},'%')
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) >= #{statisticsVo.contractAmtStr}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) <= #{statisticsVo.contractAmtEnd}
and ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) BETWEEN #{statisticsVo.contractAmtStr} AND #{statisticsVo.contractAmtEnd}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7') >= #{statisticsVo.paymentAmountStr}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7') <= #{statisticsVo.paymentAmountEnd}
AND (SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id AND ff.State = '7') BETWEEN #{statisticsVo.paymentAmountStr} AND #{statisticsVo.paymentAmountEnd}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END >= #{statisticsVo.paymentSpeedStr}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END <= #{statisticsVo.paymentSpeedEnd}
AND CASE WHEN con.Con_Money_Total IS NULL OR con.Con_Money_Total = 0 THEN '0' ELSE ROUND(COALESCE((SELECT SUM(cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = con.con_id and ff.State = '7'), 0) / COALESCE(con.Con_Money_Total, 1) * 100, 2) END BETWEEN #{statisticsVo.paymentSpeedStr} AND #{statisticsVo.paymentSpeedEnd}
AND app.sa_approved_amt >= #{statisticsVo.settlementStr}
AND app.sa_approved_amt <= #{statisticsVo.settlementEnd}
AND app.sa_approved_amt BETWEEN #{statisticsVo.settlementStr} AND #{statisticsVo.settlementEnd}
GROUP BY con.con_id, con.con_name, con.con_code, con.Con_Money_Total, pany.c_name, app.sa_approved_amt

SELECT pp.p_Name AS pName, mn.con_id as conId, mn.con_name AS contractName, mn.con_code AS contractCode, mn.con_Create_User_Id as conCreateUserId, mn.con_Create_User_Name AS conCreateUserName, total.contractAmt, pany.c_name AS companyName, total.paymentAmtTotal, mn.con_Type AS conType, CASE WHEN total.contractAmt = 0 THEN 0.00 ELSE ROUND(total.paymentAmtTotal / total.contractAmt * 100, 2) END AS fkjindu, COALESCE(app.sa_approved_amt, 0) as settlement FROM Con_Contract mn left join pre_project pp ON mn.con_project_id = pp.p_id LEFT JOIN sys_company pany ON mn.Con_Party_B_Id = pany.c_id
LEFT JOIN ( SELECT c.con_id, (c.Con_Money_Total + COALESCE(( SELECT SUM(CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -cc.Con_Sup_Change_Money ELSE 0 END) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id = c.con_id AND cc.Con_Approval_State = 7 ), 0)) AS contractAmt, COALESCE(( SELECT SUM(ff.cpaf_application) FROM Con_Pay_Apply_Flow ff WHERE ff.con_id = c.con_id AND ff.State = '7' ), 0) AS paymentAmtTotal FROM Con_Contract c ) total ON mn.con_id = total.con_id
LEFT JOIN ( SELECT con_id, MAX(sa_approved_amt) sa_approved_amt FROM Inv_Settlement_Apply GROUP BY con_id ) app ON mn.con_id = app.con_id
${authSql} AND mn.Con_Approval_State = 7 AND mn.con_Type NOT IN ('07','0701','0702','0703')
AND mn.con_name LIKE '%' || #{statisticsVo.contractName} || '%'
AND likeCname(#{statisticsVo.companyName}, pany.c_id)=true
AND pany.c_name LIKE '%' || #{statisticsVo.companyName} || '%'
AND mn.con_code LIKE '%' || #{statisticsVo.contractNumber} || '%'
AND total.paymentAmtTotal >= #{statisticsVo.paymentAmountStr}
AND total.paymentAmtTotal <= #{statisticsVo.paymentAmountEnd}
AND total.contractAmt >= #{statisticsVo.contractAmtStr}
AND total.contractAmt <= #{statisticsVo.contractAmtEnd}
AND (CASE WHEN total.contractAmt = 0 THEN 0.00 ELSE ROUND(total.paymentAmtTotal / total.contractAmt * 100, 2) END) >= #{statisticsVo.paymentSpeedStr}
AND (CASE WHEN total.contractAmt = 0 THEN 0.00 ELSE ROUND(total.paymentAmtTotal / total.contractAmt * 100, 2) END) <= #{statisticsVo.paymentSpeedEnd}
AND COALESCE(app.sa_approved_amt,0) >= #{statisticsVo.settlementStr}
AND COALESCE(app.sa_approved_amt,0) <= #{statisticsVo.settlementEnd}
GROUP BY pp.p_Name, mn.con_id, mn.con_name, mn.con_code, mn.Con_Create_User_Id, mn.Con_Create_User_Name, contractAmt, paymentAmtTotal, pany.c_name, sa_approved_amt, mn.con_Type
ORDER BY pp.p_Name ASC
